import { create } from 'zustand';
import { persist, createJSONStorage } from 'zustand/middleware';

export interface CartItem {
  id: string; // clave compuesta: `${variant_id}-${flavor_id}`
  product_id: number;
  product_title: string;
  variant_id: number;
  flavor_id: number;
  selected_weight: string;
  selected_flavor: string;
  unit_price: number;
  quantity: number;
  img_url: string | null;
  max_stock: number;
}

export type NewCartItem = Omit<CartItem, 'id'>; // incluye quantity: la cantidad que se quiere agregar

interface CartStore {
  cart: CartItem[];
  lastUpdated: number | null;
  addToCart: (item: NewCartItem) => void;
  updateQuantity: (id: string, delta: number) => void;
  removeItem: (id: string) => void;
  clearCart: () => void;
  itemCount: () => number;
}

const THREE_DAYS_IN_MS = 3 * 24 * 60 * 60 * 1000;

export const useCartStore = create<CartStore>()(
  persist(
    (set, get) => ({
      cart: [],
      lastUpdated: null,

      addToCart: (item) => {
        set((state) => {
          const compositeId = `${item.variant_id}-${item.flavor_id}`;
          const existingIndex = state.cart.findIndex((c) => c.id === compositeId);
          const incomingQty = item.quantity > 0 ? item.quantity : 1;
          let newCart: CartItem[];

          if (existingIndex > -1) {
            const current = state.cart[existingIndex];
            const newQty = Math.min(current.quantity + incomingQty, item.max_stock);

            if (newQty <= current.quantity) return state; // ya está en el tope de stock

            newCart = [...state.cart];
            newCart[existingIndex] = {
              ...current,
              unit_price: item.unit_price,
              max_stock: item.max_stock,
              quantity: newQty,
            };
          } else {
            if (item.max_stock <= 0) return state;

            const cappedQty = Math.min(incomingQty, item.max_stock);
            newCart = [...state.cart, { ...item, id: compositeId, quantity: cappedQty }];
          }

          return { cart: newCart, lastUpdated: Date.now() };
        });
      },

      updateQuantity: (id, delta) => {
        set((state) => ({
          cart: state.cart
            .map((item) => {
              if (item.id === id) {
                const newQty = item.quantity + delta;
                if (newQty <= 0) return null;
                if (delta > 0 && newQty > item.max_stock) return item;
                return { ...item, quantity: newQty };
              }
              return item;
            })
            .filter(Boolean) as CartItem[],
          lastUpdated: Date.now(),
        }));
      },

      removeItem: (id) => {
        set((state) => ({
          cart: state.cart.filter((item) => item.id !== id),
          lastUpdated: Date.now(),
        }));
      },

      clearCart: () => set({ cart: [], lastUpdated: null }),

      itemCount: () => get().cart.reduce((total, item) => total + item.quantity, 0),
    }),
    {
      name: 'cart-storage',
      storage: createJSONStorage(() => localStorage),
      onRehydrateStorage: () => (state) => {
        if (state && state.lastUpdated) {
          const now = Date.now();
          if (now - state.lastUpdated > THREE_DAYS_IN_MS) {
            state.clearCart();
          }
        }
      },
    }
  )
);